    walls=[r for r in range(h) if 8 in grid[r]]
    marker=next((c for row in grid for c,v in enumerate(row) if v==2),w//2)
    # Each 8-bar's missing cells are openings. Connect openings horizontally
    # in the blank band immediately above, and carry them vertically to next band.
    active={marker}
    for k,r in enumerate(walls):
        holes={c for c,v in enumerate(grid[r]) if v==0}
        if not holes: continue
        # vertical traces from all active tracks to row before this barrier
        for c in active:
            for rr in range(max(0, (walls[k-1]+1) if k else 0), r):
                if grid[rr][c]==0: out[rr][c]=2
        # horizontal connection runs across the gap openings on preceding blank row
        rr=r-1
        points=active|holes
        for c in range(min(points),max(points)+1):
            if grid[rr][c]==0: out[rr][c]=2
        for c in holes: out[r][c]=2
        active=holes
    # carry final channels downward
    start=walls[-1]+1 if walls else 0
    for c in active:
        for rr in range(start,h):
            if grid[rr][c]==0: out[rr][c]=2
    return out
